$(document).on("WebPlayerSeIniciaSistema",function(){var controles=ObtenerControles(["btnGuardarCalendario","btnDescargarComprobante"]);if(!controles||!controles.length){return;}
var rutaImagenes=Ciel.MPC.WebPlayer.RutaRecursos+"img/Modal/";var imgControles={"btnGuardarCalendario":"icon_calendario.svg","btnDescargarComprobante":"icon_comprobante.svg","default":"icon-help.svg"};controles.forEach(function(control){if(control.DivContenedor==undefined){return;}
var elemento=control.DivContenedor[0];if(!elemento){return;}
var rutaImagen=imgControles[control.Nombre];if(!rutaImagen){rutaImagen=imgControles["default"];}
var imgCola=document.createElement("img");imgCola.setAttribute('src',rutaImagenes+rutaImagen);var divContentImg=document.createElement("div");divContentImg.classList.add('content-imgbotonmodal');divContentImg.append(imgCola);elemento.prepend(divContentImg);});});